import {Company,PLACES,TYPES,MODES,GOODS} from './sim.mjs';
import {World} from './world.mjs';
const $=s=>document.querySelector(s),fmt=n=>Math.floor(n).toLocaleString('ko-KR'),STORE='blueport-company-v1';
let company,loaded=false;try{const raw=localStorage.getItem(STORE);if(raw){company=Company.restore(JSON.parse(raw));loaded=true}}catch{}company??=new Company();
let tab='home',wizard=null,nodeId=null,routeId=null,speed=1,paused=false,muted=true,audio,last=performance.now(),uiClock=0,saveClock=0,toastTimer,lastUnlock=company.delivered,lastWon=company.won;
try{muted=JSON.parse(localStorage.getItem('blueport-muted')??'true')}catch{}
function sound(freq=500){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*1.3,audio.currentTime+.14);g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.start();o.stop(audio.currentTime+.26)}catch{}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function persist(notify=false){try{localStorage.setItem(STORE,JSON.stringify(company));$('#saveStatus').textContent='방금 자동 저장됨';if(notify)toast('진행 상황을 저장했습니다.')}catch{$('#saveStatus').textContent='저장 공간 부족';if(notify)toast('저장에 실패했습니다. 설정에서 저장 파일을 내려받아 주세요.')}}
function dialog(content,actions){$('#modalContent').innerHTML=content;$('#modalActions').replaceChildren();for(const [name,action,primary] of actions){const b=document.createElement('button');b.textContent=name;if(primary)b.className='primary';b.onclick=()=>{$('#modal').close();action?.()};$('#modalActions').append(b)}if(!$('#modal').open)$('#modal').showModal()}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();$('#modalActions').lastElementChild?.click()});
const world=new World($('#map'),id=>{if(wizard){if(wizard.a===null){wizard.a=id;wizard.b=null}else if(id!==wizard.a)wizard.b=id;renderWizard()}else{nodeId=id;routeId=null;world.selected=id;renderPanel()}sound(330)});
function updateHeader(){const cash=$('#cash');cash.textContent=fmt(company.cash);cash.style.color=company.cash<0?'#b87561':'';$('#fleet').innerHTML=`${company.routes.reduce((s,r)=>s+r.vehicles.length,0)} <span>대</span>`;$('#delivered').innerHTML=`${fmt(company.delivered)} <span>명·톤</span>`;const d=Math.floor(company.day);$('#date').textContent=`${1+Math.floor(d/360)}년 ${1+Math.floor(d/30)%12}월 ${1+d%30}일`;$('#weather').textContent='☀ '+company.event().name;$('#weather').title=company.event().desc;$('#rank').innerHTML=company.won?'ISLAND<br>TYCOON':company.delivered>=220?'REGIONAL<br>NETWORK':company.delivered>=60?'GROWING<br>COMPANY':'LOCAL<br>OPERATOR';$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'시간 계속':'일시 정지');$('#modeButtons').querySelectorAll('button').forEach(b=>{const m=b.dataset.mode;b.disabled=!company.unlock(m);b.title=company.unlock(m)?`${MODES[m].name} 노선 건설`:`누적 ${MODES[m].unlock}명·톤 운송 후 해제`;b.classList.toggle('selected',wizard?.mode===m)})}
for(const [id,m] of Object.entries(MODES)){const b=document.createElement('button');b.dataset.mode=id;b.innerHTML=`<i>${m.icon}</i><span>${m.name}</span>`;b.setAttribute('aria-label',m.name+' 노선 건설');b.onclick=()=>begin(id);$('#modeButtons').append(b)}
function begin(mode){if(!company.unlock(mode)){toast(`누적 ${MODES[mode].unlock}명·톤 운송 후 사용할 수 있습니다.`);return}wizard={mode,a:nodeId,b:null};routeId=null;nodeId=null;renderWizard();updateHeader();if(innerWidth<700)$('#panel').scrollIntoView({behavior:'smooth',block:'nearest'})}
function clearSelection(){wizard=null;nodeId=null;routeId=null;world.preview=null;world.selected=null;renderPanel();updateHeader()}
function switchTab(name){tab=name;clearSelection();$('.tabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab))}
$('.tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('#brand').onclick=e=>{e.preventDefault();switchTab('home');world.reset()};$('#zoomIn').onclick=()=>world.changeZoom(1.25);$('#zoomOut').onclick=()=>world.changeZoom(.8);$('#resetView').onclick=()=>world.reset();$('#pause').onclick=()=>{paused=!paused;updateHeader()};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);paused=false;document.querySelectorAll('[data-speed]').forEach(x=>x.classList.toggle('active',x===b));updateHeader()});
function goalCard(){const index=Math.min(4,company.milestones.length),g=company.goalData()[index],pct=Math.min(100,g.value/g.target*100);return `<div class="overview-card"><span class="chapter">CHAPTER ${String(index+1).padStart(2,'0')} / 05</span><h3>${company.won?'섬의 모든 길을 연결했습니다':g.name}</h3><p>${company.won?'새로운 노선과 더 큰 도시를 만들어 보세요. 자유 경영은 계속됩니다.':g.desc}</p><div class="progress"><i style="width:${company.won?100:pct}%"></i></div><div class="progress-label"><span>${company.won?'자유 경영 모드':Math.floor(pct)+'% 달성'}</span><span>목표 보상 ${fmt(g.reward)}</span></div></div>`}
function cityList(){return `<div class="place-list">${company.nodes.map(n=>`<button class="place-row" data-node="${n.id}"><i>${n.type==='city'?'⌂':GOODS[TYPES[n.type].out].icon}</i><div><b>${n.name}</b><small>${TYPES[n.type].name} · ${n.type==='city'?fmt(n.pop)+'명':GOODS[TYPES[n.type].out].name+' 생산'}</small></div><span>↗</span></button>`).join('')}</div>`}
function homePanel(){return `${goalCard()}<div class="stats-grid"><div><small>기업 가치</small><strong>${fmt(company.worth())}</strong></div><div><small>이달 운송 수익</small><strong>${fmt(company.monthIncome)}</strong></div><div><small>연결한 노선</small><strong>${company.routes.length}<small>노선</small></strong></div><div><small>총 운행 거리</small><strong>${fmt(company.routes.reduce((s,r)=>s+r.distance,0))}<small>km</small></strong></div></div>${!company.routes.length?'<button id="recommended" class="primary warm">첫 노선 추천 · 숲 → 제재소 ↗</button><p class="hint">노선을 개통하면 역과 차량이 함께 준비됩니다.</p>':''}<div class="note"><b>${company.event().name}</b><br>${company.event().desc}</div><div class="section-title"><span>도시와 산업</span><small>14 DESTINATIONS</small></div>${cityList()}`}
function routeCards(){return company.routes.length?`<div class="route-list">${company.routes.map(r=>`<button class="route-card" data-route="${r.id}" style="--route:${MODES[r.mode].color}"><div class="route-head"><b>${MODES[r.mode].icon} ${company.nodes[r.a].name} → ${company.nodes[r.b].name}</b></div><div class="line"><i></i>${GOODS[r.cargo].name} · ${r.vehicles.length}대 · ${r.enabled?'운행 중':'운휴 중'}</div><div class="route-foot"><span>누적 순익 ${fmt(r.revenue-r.cost)}</span><small>${fmt(r.deliveries)}명·톤</small></div></button>`).join('')}</div>`:'<div class="note">아직 노선이 없습니다.<br>아래에서 운송수단을 선택하고 두 지점을 연결하세요.</div>'}
function routeDetail(r){const m=MODES[r.mode];return `<button class="panel-back" id="back">← 노선 목록</button><p class="eyebrow">${m.name} / ROUTE ${String(r.id).padStart(2,'0')}</p><h3>${company.nodes[r.a].name}<br>↳ ${company.nodes[r.b].name}</h3><span class="badge">${GOODS[r.cargo].name} · ${fmt(r.distance)}km</span><div class="stats-grid"><div><small>누적 수입</small><strong>${fmt(r.revenue)}</strong></div><div><small>누적 운영비</small><strong>${fmt(r.cost)}</strong></div></div><div class="detail-actions"><button id="toggleRoute">${r.enabled?'운행 일시 중지':'운행 재개'}</button><button id="removeRoute">노선 철거</button></div><h3>운행 차량 ${r.vehicles.length} / 6</h3>${r.vehicles.map(v=>`<div class="vehicle-card"><div><b>${m.vehicle} #${v.id} · Lv.${v.level}</b><small>${v.wait>0?'상·하차 중':v.dir>0?'출발지 → 도착지':'복귀 중'}</small></div><small>적재 ${v.load} / ${Math.floor(m.cap*(1+.35*(v.level-1)))} · 상태 ${Math.floor(v.condition)}%</small><div class="progress"><i style="width:${v.condition}%"></i></div><div class="vehicle-buttons"><button data-upgrade="${v.id}" ${v.level>=3?'disabled':''}>${v.level>=3?'최고 성능':'성능 + '+fmt(m.cost*.65*v.level)}</button><button data-replace="${v.id}">교체 ${fmt(m.cost*.55)}</button><button data-sell="${v.id}" ${r.vehicles.length<=1?'disabled':''}>매각</button></div></div>`).join('')}<button id="addVehicle" class="primary" ${r.vehicles.length>=6?'disabled':''}>차량 추가 · ${fmt(m.cost)}</button><p class="hint">차량이 늘면 터미널이 혼잡해집니다. 출발지와 도착지의 시설을 확장하면 혼잡과 상·하차 시간이 줄어듭니다.</p>`}
function nodePanel(n){const t=TYPES[n.type];return `<button class="panel-back" id="back">← 회사 개요</button><p class="eyebrow">${n.coast?'COASTAL / ':''}${t.name}</p><h3>${n.name}</h3><span class="badge">${n.type==='city'?'인구 '+fmt(n.pop)+'명':t.recipe?Object.keys(t.recipe).map(k=>GOODS[k].name).join('')+' → '+GOODS[t.out].name:GOODS[t.out].name+' 생산'}</span><div class="inventory">${Object.entries(n.stock).map(([k,v])=>`<div><small>${GOODS[k]?.name||k} 대기</small><b>${fmt(v)}</b></div>`).join('')}</div><p class="hint">${t.accept.length?'수요: '+t.accept.map(k=>GOODS[k].name).join(' · '):'원자재를 생산하는 시설입니다.'}${n.type==='city'?'<br>승객과 완제품이 도착하면 도시가 성장합니다.':''}</p><button id="fromHere" class="primary">이곳에서 새 노선 출발</button><div class="section-title"><span>운송 시설</span><small>TERMINALS</small></div>${Object.entries(n.facilities).map(([k,v])=>`<div class="facility"><span>${{rail:'철도역',road:'정류장·물류장',port:'항구',air:'공항'}[k]} Lv.${v}</span><button data-facility="${k}" ${v>=3?'disabled':''}>${v>=3?'최대 확장':'확장 '+fmt(800*v)}</button></div>`).join('')||'<p class="hint">노선을 개통하면 필요한 시설이 자동 건설됩니다.</p>'}<div class="section-title"><span>이곳의 노선</span></div><div class="route-list">${company.routes.filter(r=>r.a===n.id||r.b===n.id).map(r=>`<button class="place-row" data-route="${r.id}">${MODES[r.mode].icon} ${company.nodes[r.a].name} ↔ ${company.nodes[r.b].name}</button>`).join('')||'<p class="hint">아직 연결된 노선이 없습니다.</p>'}</div>`}
function contractCard(c,active){return `<div class="contract"><small>${active?'진행 중인 운송 계약':'지역 운송 의뢰'}</small><h4>${company.nodes[c.a].name}<br>→ ${company.nodes[c.b].name}</h4><p>${GOODS[c.cargo].name} ${c.amount}명·톤 납품 · 남은 기간 ${Math.max(0,Math.ceil(c.deadline-company.day))}일</p>${active?`<div class="progress"><i style="width:${Math.min(100,c.done/c.amount*100)}%"></i></div><p>${c.done} / ${c.amount} 납품</p>`:''}<div><span>완료 보상</span><b>${fmt(c.reward)}</b></div>${active?`<button data-plan-contract="${c.id}">계약 노선 계획하기</button>`:`<button data-contract="${c.id}" ${company.activeContract?'disabled':''}>계약 수락</button>`}</div>`}
function financePanel(){const h=company.history,max=Math.max(1,...h.map(m=>Math.max(m.income,m.cost)));return `<p class="eyebrow">COMPANY FINANCES</p><h3>차곡차곡 쌓이는 성장</h3><div class="stats-grid"><div><small>총 운송 수입</small><strong>${fmt(company.revenue)}</strong></div><div><small>운영 자금</small><strong>${fmt(company.cash)}</strong></div><div><small>대출 잔액</small><strong>${fmt(company.loan)}</strong></div><div><small>현재 기업 가치</small><strong>${fmt(company.worth())}</strong></div></div><div class="section-title"><span>월별 운송 수입과 운영비</span></div><div class="chart">${h.map(m=>`<div title="${m.month}월 수입 ${fmt(m.income)} / 비용 ${fmt(m.cost)}"><i style="height:${m.income/max*100}%"></i><i class="cost" style="height:${m.cost/max*100}%"></i></div>`).join('')||'<p class="hint">첫 달 정산 후 그래프가 표시됩니다.</p>'}</div><p class="hint">초록: 수입 · 갈색: 차량·노선 운영비 및 이자<br>건설비와 차량 구입비는 별도 자산 투자입니다.</p>${h.slice(-4).reverse().map(m=>`<div class="history-row"><span>${m.month}개월차</span><span class="${m.income-m.cost>=0?'success':'danger'}">${m.income-m.cost>=0?'+':''}${fmt(m.income-m.cost)}</span></div>`).join('')}<div class="section-title"><span>운영 자금 대출</span><small>월 이자 2%</small></div><div class="detail-actions"><button id="borrow" ${company.loan>=30000?'disabled':''}>10,000 대출</button><button id="repay" ${company.loan<=0?'disabled':''}>10,000 상환</button></div><p class="hint">총 30,000까지 대출할 수 있습니다. 적자 노선의 차량을 줄이거나 운행을 중지하면 유지비가 줄어듭니다.</p>`}
function renderPanel(){if(wizard){renderWizard();return}const p=$('#panel'),r=company.routes.find(r=>r.id===routeId);if(nodeId!==null)p.innerHTML=nodePanel(company.nodes[nodeId]);else if(r)p.innerHTML=routeDetail(r);else if(tab==='home')p.innerHTML=homePanel();else if(tab==='routes')p.innerHTML=`<p class="eyebrow">YOUR TRANSPORT NETWORK</p><h3>섬을 연결하는 ${company.routes.length}개 노선</h3>${routeCards()}`;else if(tab==='contracts')p.innerHTML=`<p class="eyebrow">LOCAL OPPORTUNITIES</p><h3>지역과 함께 성장하기</h3>${company.activeContract?contractCard(company.activeContract,true):'<p class="hint">계약은 한 번에 하나씩 진행합니다. 기한 내 운송을 완료하면 운임 외 추가 보상을 받습니다.</p>'}${company.contracts.map(c=>contractCard(c,false)).join('')}`;else p.innerHTML=financePanel();bindPanel();}
function bindPanel(){const p=$('#panel');p.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{nodeId=Number(b.dataset.node);routeId=null;world.focus(company.nodes[nodeId]);renderPanel()});p.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{routeId=Number(b.dataset.route);nodeId=null;const r=company.routes.find(r=>r.id===routeId);world.focus(company.nodes[r.a]);renderPanel()});$('#back')?.addEventListener('click',()=>{routeId=null;nodeId=null;world.selected=null;renderPanel()});$('#recommended')?.addEventListener('click',()=>{wizard={mode:'train',a:6,b:7};world.focus(company.nodes[6]);renderWizard();updateHeader()});$('#fromHere')?.addEventListener('click',()=>begin(company.nodes[nodeId].type==='city'?'bus':'truck'));
 p.querySelectorAll('[data-facility]').forEach(b=>b.onclick=()=>{if(company.upgradeFacility(nodeId,b.dataset.facility)){toast('시설을 확장했습니다. 상·하차가 빨라집니다.');sound(650);persist()}else toast('시설 확장에 필요한 자금이 부족합니다.');renderPanel();updateHeader()});const r=company.routes.find(r=>r.id===routeId);if(r){$('#toggleRoute').onclick=()=>{r.enabled=!r.enabled;renderPanel();persist()};$('#removeRoute').onclick=()=>dialog('<p class="eyebrow">REMOVE ROUTE</p><h2>노선을 철거할까요?</h2><p>시설 투자비의 65%, 차량 잔존 가치의 55%가 회수됩니다. 운송 중인 화물은 출발지 재고로 돌아갑니다.</p>',[['철거하고 회수',()=>{company.removeRoute(r.id);routeId=null;renderPanel();persist();updateHeader()}],['유지하기',()=>{},true]]);$('#addVehicle').onclick=()=>action(()=>company.addVehicle(r.id),'차량을 추가했습니다.');p.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>action(()=>company.upgradeVehicle(r.id,Number(b.dataset.upgrade)),'속도와 적재량이 향상됐습니다.'));p.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>action(()=>company.replaceVehicle(r.id,Number(b.dataset.replace)),'새 차량으로 교체했습니다.'));p.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>action(()=>company.sellVehicle(r.id,Number(b.dataset.sell)),'차량을 매각했습니다.'));}
 p.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>{if(company.acceptContract(Number(b.dataset.contract))){toast('계약을 수락했습니다. 정해진 구간으로 화물을 운송하세요.');persist();renderPanel()}});p.querySelectorAll('[data-plan-contract]').forEach(b=>b.onclick=()=>{const c=company.activeContract;wizard={mode:c.cargo==='passengers'?'bus':'truck',a:c.a,b:c.b};renderWizard();updateHeader()});$('#borrow')?.addEventListener('click',()=>action(()=>company.borrow(),'운영 자금 10,000을 확보했습니다.'));$('#repay')?.addEventListener('click',()=>action(()=>company.repay(),'대출을 상환했습니다.'));}
function action(fn,message){if(fn()){toast(message);sound(600);persist()}else toast('자금 또는 이용 조건을 확인하세요.');renderPanel();updateHeader()}
function renderWizard(){const {mode,a,b}=wizard,m=MODES[mode];const eligible=company.nodes.filter(n=>(mode!=='ship'||n.coast)&&(mode!=='bus'&&mode!=='plane'||n.type==='city')&&(mode!=='truck'||n.type!=='city'));if(a!==null&&!eligible.some(n=>n.id===a)){wizard.a=null;wizard.b=null}const from=company.nodes[wizard.a],cargo=from?TYPES[from.type].out:null,destinations=from?company.nodes.filter(n=>company.validCargo(from,n,cargo,mode)):[];if(wizard.b!==null&&!destinations.some(n=>n.id===wizard.b))wizard.b=null;const q=from&&wizard.b!==null?company.quote(from.id,wizard.b,mode,cargo):null;world.preview=q&&!q.error?q:null;world.selected=wizard.a;
 $('#panel').innerHTML=`<p class="eyebrow">BUILD A CONNECTION</p><h3>${m.icon} ${m.name} 노선 건설</h3><p class="hint">지도에서 두 지점을 누르거나 아래 목록에서 선택하세요. 건설 전까지 비용은 발생하지 않습니다.</p><label class="field-label" for="from">01 · 출발지</label><select id="from"><option value="">선택하세요</option>${eligible.map(n=>`<option value="${n.id}" ${n.id===wizard.a?'selected':''}>${n.name} · ${GOODS[TYPES[n.type].out].name}</option>`).join('')}</select><label class="field-label" for="to">02 · 도착지</label><select id="to" ${!from?'disabled':''}><option value="">${from?'수요가 있는 목적지를 선택하세요':'출발지를 먼저 선택하세요'}</option>${destinations.map(n=>`<option value="${n.id}" ${n.id===wizard.b?'selected':''}>${n.name}</option>`).join('')}</select>${from?`<p class="hint">운송 화물: <b>${GOODS[cargo].name}</b> · 출발지 대기 ${fmt(from.stock[cargo]||0)}<br>${cargo==='passengers'?'양쪽 도시에서 승객을 태워 왕복합니다.':'화물을 납품한 뒤 빈 차량으로 복귀합니다.'}</p>`:''}${q? q.error?`<p class="error">${q.error}</p>`:`<div class="quote"><div><span>노선 길이</span><b>${fmt(q.distance)}km${q.bridge?' · 교량 '+q.bridge+'구간':''}</b></div><div><span>기반 시설·터미널</span><b>${fmt(q.infra)}</b></div><div><span>${m.vehicle} 1대</span><b>${fmt(q.vehicle)}</b></div><div class="total"><span>총 건설비</span><strong>${fmt(q.total)}</strong></div></div><p class="hint">시설 자동 건설 · 차량 월 유지비 ${m.upkeep}<br>역·정류장·항구·공항은 노선 상세에서 확장할 수 있습니다.</p>`:'<div class="note">처음에는 가까운 도시 두 곳, 또는 원자재 생산지와 공장을 연결해 보세요.</div>'}<button id="confirmBuild" class="primary" ${!q||q.error||q.total>company.cash?'disabled':''}>${q&&q.total>company.cash?'자금 부족':'노선 건설 · 운행 시작'}</button><button id="cancelBuild" class="cancel-build">건설 취소</button>`;
 $('#from').onchange=e=>{wizard.a=e.target.value===''?null:Number(e.target.value);wizard.b=null;renderWizard()};$('#to').onchange=e=>{wizard.b=e.target.value===''?null:Number(e.target.value);renderWizard()};$('#cancelBuild').onclick=clearSelection;$('#confirmBuild').onclick=()=>{const result=company.build(wizard.a,wizard.b,mode,cargo);if(result.error){toast(result.error);return}wizard=null;world.preview=null;tab='routes';routeId=result.id;nodeId=null;$('.tabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.tab==='routes'));renderPanel();updateHeader();persist();sound(700);toast('노선이 개통됐습니다. 차량이 곧 출발합니다.');};}
function manual(){dialog('<p class="eyebrow">THE BLUEPORT HANDBOOK</p><h2>길이 생기면, 도시가 자랍니다.</h2><div class="manual-item"><b>01 · 노선 만들기</b>하단 운송수단을 고르고 출발지와 도착지를 선택하세요. 미리 표시되는 경로와 건설비를 확인한 뒤 개통합니다. 역과 차량이 함께 준비됩니다.</div><div class="manual-item"><b>02 · 산업 연결하기</b>푸른숲 → 제재소 → 도시(생활용품)<br>광산 → 제철소 → 제조소 → 도시(생활용품)<br>농장 → 식품공장 → 도시(식품)<br>공장에 원자재가 없으면 제품도 생산되지 않습니다.</div><div class="manual-item"><b>03 · 바다와 하늘로</b>누적 60명·톤 운송하면 선박, 220명·톤이면 항공기가 해제됩니다. 항구는 해안 시설만 연결하며 비행기는 도시 간 승객을 운송합니다.</div><div class="manual-item"><b>04 · 운영과 성장</b>노선에서 차량을 추가·개량·교체하세요. 역과 항구 등의 시설 확장은 혼잡을 줄입니다. 계약과 5단계 회사 목표를 완료하면 보상을 받습니다.</div><div class="manual-item"><b>05 · 저장과 조작</b>진행은 자동 저장됩니다. 다른 기기로 옮기려면 설정에서 저장 파일을 내보내세요. 드래그로 지도 이동, 스크롤·두 손가락으로 확대. Space로 일시 정지.</div>',[['플레이 계속',()=>{},true]])}
$('#help').onclick=manual;$('#sound').classList.toggle('muted',muted);$('#sound').onclick=()=>{muted=!muted;try{localStorage.setItem('blueport-muted',JSON.stringify(muted))}catch{}$('#sound').classList.toggle('muted',muted);$('#sound').setAttribute('aria-label',muted?'효과음 켜기':'효과음 끄기');sound()};
function settings(){dialog('<p class="eyebrow">COMPANY ARCHIVE</p><h2>저장 및 설정</h2><p>이 브라우저에 30초마다 자동 저장합니다.<br>새 기기에서는 저장 파일을 가져오면 이어할 수 있습니다.</p>',[['지금 저장',()=>persist(true),true],['저장 파일 내보내기',()=>{const blob=new Blob([JSON.stringify(company,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='blueport-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}],['저장 파일 가져오기',()=>$('#importFile').click()],['효과음 '+(muted?'켜기':'끄기'),()=>$('#sound').click()],['새 회사 시작',()=>dialog('<h2>처음부터 시작할까요?</h2><p>현재 회사의 자동 저장 기록이 새 회사로 바뀝니다. 보관하려면 먼저 저장 파일을 내보내세요.</p>',[['새 회사 시작',()=>{company=new Company();lastWon=false;lastUnlock=0;tab='home';clearSelection();world.reset();persist();updateHeader();toast('새로운 블루포트 교통이 출범했습니다.')}],['돌아가기',settings,true]])],['닫기',()=>{}]])}
$('#settings').onclick=settings;$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('파일이 너무 큽니다.');const next=Company.restore(JSON.parse(await file.text()));dialog('<h2>저장한 회사를 불러올까요?</h2><p>현재 회사는 가져온 저장 기록으로 바뀝니다.</p>',[['불러오기',()=>{company=next;lastWon=company.won;lastUnlock=company.delivered;clearSelection();updateHeader();persist();toast('저장한 회사를 불러왔습니다.')},true],['취소',()=>{}]])}catch{toast('유효한 블루포트 저장 파일이 아닙니다.')}e.target.value=''};
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!$('#modal').open&&!['SELECT','INPUT'].includes(e.target.tagName)){e.preventDefault();paused=!paused;updateHeader()}if(e.key==='Escape'&&wizard&&!$('#modal').open)clearSelection()});document.addEventListener('visibilitychange',()=>{if(document.hidden){paused=true;persist();updateHeader()}});window.addEventListener('pagehide',()=>persist());
function refreshPanel(){if(wizard){const q=wizard.a!==null&&wizard.b!==null?company.quote(wizard.a,wizard.b,wizard.mode,TYPES[company.nodes[wizard.a].type].out):null;$('#confirmBuild').disabled=!q||!!q.error||q.total>company.cash;return}const el=document.activeElement;if(!$('#panel').contains(el))renderPanel();}
function loop(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(!paused&&!$('#modal').open){const elapsed=dt*.45*speed;company.step(elapsed);saveClock+=dt;}world.draw(company,paused?0:dt);uiClock+=dt;if(uiClock>.6){uiClock=0;updateHeader();refreshPanel();if(company.notices.length)toast(company.notices.shift());for(const [k,m] of Object.entries(MODES))if(lastUnlock<m.unlock&&company.delivered>=m.unlock){toast(`${m.name} 운송이 해제됐습니다!`);sound(900)}lastUnlock=company.delivered;if(company.won&&!lastWon){lastWon=true;persist();dialog('<p class="eyebrow">CAMPAIGN COMPLETE</p><div class="large-mark">✦</div><h2>섬의 모든 길이 당신에게 이어집니다.</h2><p>5단계 회사 목표를 모두 달성했습니다.<br>철도·도로·바다·하늘의 교통망이 완성됐습니다.<br>이제 자유 경영으로 더 큰 도시와 더 아름다운 노선을 만들어 보세요.</p>',[['자유 경영 계속',()=>{},true]])}}
 if(saveClock>30||company.autosaveDue){saveClock=0;company.autosaveDue=false;persist()}requestAnimationFrame(loop)}
renderPanel();updateHeader();requestAnimationFrame(loop);
if(!loaded)dialog('<p class="eyebrow">WELCOME TO BLUEPORT</p><div class="large-mark">≈</div><h2>당신의 첫 노선이<br>섬의 내일을 만듭니다.</h2><p>기차, 버스, 트럭, 배, 비행기로 도시와 산업을 연결하세요. 화물을 운송하고, 수익을 재투자해 작은 회사를 섬 전체의 교통기업으로 키워보세요.</p><div class="note">시작 자금 <b>28,000</b><br>추천 첫 노선: 푸른숲 → 솔빛 제재소<br>5단계 목표 완료 후에도 자유 경영이 계속됩니다.</div>',[['회사 운영 시작',()=>{persist();toast('하단에서 운송수단을 선택하거나 추천 노선으로 시작하세요.')},true],['게임 방법 먼저 보기',manual]]);
